def cyclic_range_sum(arr: list[int], l: int, r: int) -> int:
    MOD = 10**9 + 7
    n = len(arr)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + arr[i]
    def get_sum(k):
        if k <= 0:
            return 0
        full_cycles = k // n
        rem = k % n
        return full_cycles * prefix[n] + prefix[rem]
    return (get_sum(r) - get_sum(l - 1)) % MOD
